<section class="panel"><header class="panel-head"><div><span class="eyebrow">Three-way match intelligence</span><h2>PO → accepted receipt → invoice</h2></div><?= $match?badge($match['match_status']):badge('not_matched') ?></header><?php if($invoice): ?><article class="fulfillment-card <?= !$match?'':(in_array($match['match_status'],['matched','within_tolerance'],true)?'match-good':($match['match_status']==='blocked'?'match-block':'match-warn')) ?>"><h3><?= h($invoice['invoice_number']) ?> · <?= money($invoice['total_amount']) ?></h3><p><?= h($invoice['hold_reason']?:'No active payment hold.') ?></p><?php if($match): ?><div class="fulfillment-kpis"><div><span>Match score</span><strong><?= number_format((float)$match['match_score'],1) ?></strong></div><div><span>Accepted value</span><strong><?= money($match['accepted_receipt_value']) ?></strong></div><div><span>Exception exposure</span><strong><?= money(abs((float)$match['quantity_variance'])+abs((float)$match['price_variance'])+abs((float)$match['freight_variance'])+abs((float)$match['tax_variance'])+(float)$match['held_rejected_value']) ?></strong></div></div><p>Quantity <?= money($match['quantity_variance']) ?> · price <?= money($match['price_variance']) ?> · contract <?= money($match['contract_variance']) ?> · freight <?= money($match['freight_variance']) ?> · tax <?= money($match['tax_variance']) ?> · unreceived <?= money($match['unreceived_value']) ?>.</p><?php endif; ?></article><?php if(can('purchase_orders.review')&&$invoiceLines): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="run_match"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><label><span>Dollar tolerance</span><input type="number" min="0" step="0.01" name="tolerance_amount" value="100"></label><label><span>Percentage tolerance</span><input type="number" min="0" max="25" step="0.1" name="tolerance_pct" value="2"></label><label class="span-2"><span>Match evidence</span><textarea name="evidence_note" required>Compared purchase order, accepted receipt, contract price, invoice lines, freight, tax, duplicate fingerprint, remaining PO balance, quality holds, and prior invoice value.</textarea></label><div class="span-2 inline-actions"><button class="button primary" type="submit">Run Three-Way Match</button></div></form><?php endif; ?><?php else: ?><?php render_empty_state('Select or create an invoice','Invoice matching requires a supplier invoice header and line evidence.'); ?><?php endif; ?></section>
